# Auto-generated embedded templates
TEMPLATES = {
    "availability.html": "{% extends \"base.html\" %}\n{% block title %}Product Availability \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Product Availability at Source</h1>\n<p class=\"sub\">Enter available quantity (MT) by Source and OMC. Daily Demand cannot exceed this.</p>\n{% if user.role == 'source' %}\n<div class=\"alert {{ 'a-ok' if mod_ok else 'a-e' }}\">\n  <strong>{{ 'Edit window OPEN' if mod_ok else 'Edit window LOCKED' }}</strong> \u2014 {{ mod_msg }}<br>\n  <small>Effective window: {{ effective_window }} \u00b7 Now: {{ now_ist_str }}</small>\n</div>\n{% endif %}\n<div class=\"sec\">\n  <h2>Set / Update Availability</h2>\n  {% if user.role == 'source' and not mod_ok %}\n  <p style=\"color:#991b1b;font-weight:600;margin-bottom:.75rem\">You cannot set availability right now. Please try between 12:00 and 21:00 IST.</p>\n  {% endif %}\n  <form method=\"post\">\n    <div class=\"frm\">\n      <div class=\"fg\">\n        <label>Source *</label>\n        <select name=\"source\" required {% if user.role=='source' %}disabled{% endif %}>\n          {% for s in allowed_sources %}\n          <option value=\"{{ s }}\">{{ s }}</option>\n          {% endfor %}\n        </select>\n        {% if user.role=='source' %}<input type=\"hidden\" name=\"source\" value=\"{{ user.source }}\">{% endif %}\n      </div>\n      <div class=\"fg\">\n        <label>OMC *</label>\n        <select name=\"omc\" required>\n          {% for o in OMCS %}<option value=\"{{ o }}\">{{ o }}</option>{% endfor %}\n        </select>\n      </div>\n      <div class=\"fg\">\n        <label>Available Qty (MT) *</label>\n        <input type=\"number\" name=\"qty\" step=\"0.001\" min=\"0\" required placeholder=\"e.g. 1000\">\n      </div>\n      <div class=\"fg\">\n        <label>Effective Date</label>\n        <input type=\"date\" name=\"date\" value=\"{{ today }}\">\n      </div>\n    </div>\n    {% if user.role == 'source' and not mod_ok %}\n    <button class=\"btn btn-p\" type=\"button\" disabled style=\"opacity:.5\">Save Availability (Locked)</button>\n    {% else %}\n    <button class=\"btn btn-p\" type=\"submit\">Save Availability</button>\n    {% endif %}\n  </form>\n</div>\n<div class=\"sec\">\n  <h2>Current Product Availability</h2>\n  <div class=\"date-bar\">\n    <form method=\"get\" style=\"display:flex;gap:.5rem;align-items:center\">\n      <label>Filter by Date:</label>\n      <input type=\"date\" name=\"date\" value=\"{{ date_f }}\">\n      <button class=\"btn btn-p btn-sm\" type=\"submit\">Apply</button>\n      <a class=\"btn btn-sm\" style=\"background:#64748b\" href=\"{{ url_for('availability') }}\">All</a>\n    </form>\n  </div>\n  <table>\n    <thead><tr><th>Source</th><th>OMC</th><th>Available (MT)</th><th>Booked (MT)</th><th>Balance (MT)</th><th>Date</th>{% if user.role=='master' %}<th>Action</th>{% endif %}</tr></thead>\n    <tbody>\n    {% for a in rows %}\n      {% set b = booked.get((a.source, a.omc, a.date), 0) %}\n      {% set bal = a.qty - b %}\n      <tr>\n        <td>{{ a.source }}</td>\n        <td><strong>{{ a.omc }}</strong></td>\n        <td>{{ '%.2f'|format(a.qty) }}</td>\n        <td>{{ '%.2f'|format(b) }}</td>\n        <td style=\"{{ 'color:#dc2626;font-weight:700' if bal<0 else '' }}\">{{ '%.2f'|format(bal) }}</td>\n        <td>{{ a.date }}</td>\n        {% if user.role=='master' %}\n        <td>\n          <form method=\"post\" action=\"{{ url_for('delete_availability', aid=a.id) }}\" style=\"display:inline\" onsubmit=\"return confirm('Delete?')\">\n            <button class=\"btn btn-e btn-sm\" type=\"submit\">Del</button>\n          </form>\n        </td>\n        {% endif %}\n      </tr>\n    {% else %}\n      <tr><td colspan=\"7\" style=\"text-align:center\">No records</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"sec\">\n  <h2>Source-wise Availability Matrix (Latest)</h2>\n  <table>\n    <thead><tr><th>Source</th><th>IOCL (MT)</th><th>BPCL (MT)</th><th>HPCL (MT)</th><th>Total (MT)</th></tr></thead>\n    <tbody>\n    {% for s in SOURCES %}\n      {% set r = matrix[s] %}\n      <tr>\n        <td><strong>{{ s }}</strong></td>\n        <td>{{ '%.2f'|format(r.IOCL) }}</td>\n        <td>{{ '%.2f'|format(r.BPCL) }}</td>\n        <td>{{ '%.2f'|format(r.HPCL) }}</td>\n        <td><strong>{{ '%.2f'|format(r.IOCL+r.BPCL+r.HPCL) }}</strong></td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endblock %}\n",
    "base.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>{% block title %}KGPL LPG System{% endblock %}</title>\n<style>\n:root{--p:#1F4E79;--pd:#163a5c;--bg:#f0f4f8;--c:#fff;--t:#1a2533;--m:#64748b;--ok:#16a34a;--er:#dc2626;--bd:#e2e8f0}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:system-ui,-apple-system,sans-serif;background:var(--bg);color:var(--t);min-height:100vh}\n.nav{background:var(--p);color:#fff;padding:.7rem 1.15rem;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.5rem}\n.nav .brand{font-weight:700;font-size:1.05rem}\n.nav .brand small{display:block;font-weight:400;opacity:.8;font-size:.72rem}\n.tabs{display:flex;gap:.2rem;flex-wrap:wrap}\n.tabs a{color:#fff;text-decoration:none;padding:.35rem .7rem;border-radius:6px;font-size:.84rem;font-weight:500}\n.tabs a:hover,.tabs a.on{background:rgba(255,255,255,.2)}\n.nav-right{display:flex;align-items:center;gap:.55rem;font-size:.8rem}\n.nav-right a{color:#fff;text-decoration:none;background:rgba(255,255,255,.15);padding:.28rem .55rem;border-radius:6px}\n.wrap{max-width:1200px;margin:0 auto;padding:1.1rem}\nh1{font-size:1.25rem;color:var(--p);margin-bottom:.15rem}\n.sub{color:var(--m);font-size:.86rem;margin-bottom:.9rem}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.75rem;margin-bottom:1rem}\n.card{background:var(--c);border-radius:10px;padding:.9rem 1rem;border:1px solid var(--bd)}\n.card .l{font-size:.68rem;color:var(--m);text-transform:uppercase;font-weight:600}\n.card .v{font-size:1.25rem;font-weight:700;color:var(--p);margin-top:.1rem}\n.sec{background:var(--c);border-radius:10px;padding:1rem;margin-bottom:1rem;border:1px solid var(--bd)}\n.sec h2{font-size:.95rem;color:var(--p);margin-bottom:.6rem;padding-bottom:.3rem;border-bottom:2px solid #e8eef5}\ntable{width:100%;border-collapse:collapse;font-size:.85rem}\nth,td{padding:.45rem .55rem;text-align:left;border-bottom:1px solid var(--bd)}\nth{background:var(--p);color:#fff;font-size:.74rem;text-transform:uppercase}\ntr:nth-child(even){background:#f8fafc}\n.btn{display:inline-block;padding:.38rem .8rem;border-radius:6px;border:none;font-size:.84rem;font-weight:600;cursor:pointer;color:#fff;text-decoration:none}\n.btn-p{background:var(--p)}.btn-ok{background:var(--ok)}.btn-e{background:var(--er)}.btn-sm{padding:.2rem .45rem;font-size:.76rem}\n.frm{display:flex;flex-wrap:wrap;gap:.7rem;margin-bottom:.7rem}\n.fg{display:flex;flex-direction:column;gap:.2rem;flex:1;min-width:120px}\n.fg label{font-size:.72rem;font-weight:600;color:var(--m)}\n.fg input,.fg select{padding:.4rem .55rem;border:1px solid var(--bd);border-radius:6px;font-size:.86rem}\n.alert{padding:.55rem .8rem;border-radius:8px;margin-bottom:.8rem;font-size:.86rem}\n.a-ok{background:#dcfce7;color:#166534}.a-e{background:#fee2e2;color:#991b1b}\n.g{background:#dcfce7!important}.r{background:#fee2e2!important}\n.date-bar{display:flex;align-items:center;gap:.6rem;margin-bottom:.85rem;flex-wrap:wrap;font-size:.84rem}\n.foot{text-align:center;padding:1rem;color:var(--m);font-size:.74rem}\n@media(max-width:700px){.cards{grid-template-columns:1fr 1fr}}\n</style>\n</head>\n<body>\n{% if user %}\n<nav class=\"nav\">\n  <div class=\"brand\">KGPL LPG System<small>Kandla\u2013Gorakhpur Pipeline \u00b7 IHB</small></div>\n  <div class=\"tabs\">\n    {% if user.role != 'source' %}\n    <a href=\"{{ url_for('dashboard') }}\" class=\"{{ 'on' if request.endpoint=='dashboard' else '' }}\">Dashboard</a>\n    {% endif %}\n    {% if user.role in ('master','source') %}\n    <a href=\"{{ url_for('availability') }}\" class=\"{{ 'on' if request.endpoint=='availability' else '' }}\">Product Availability</a>\n    {% endif %}\n    {% if user.role in ('master','plant') %}\n    <a href=\"{{ url_for('demand') }}\" class=\"{{ 'on' if request.endpoint=='demand' else '' }}\">Daily Demand</a>\n    {% endif %}\n    {% if user.role == 'master' %}\n    <a href=\"{{ url_for('pumping') }}\" class=\"{{ 'on' if request.endpoint=='pumping' else '' }}\">Pumping Planning</a>\n    {% endif %}\n    <a href=\"{{ url_for('schedule_view') }}\" class=\"{{ 'on' if request.endpoint=='schedule_view' else '' }}\">Schedule</a>\n    {% if user.role != 'source' %}\n    <a href=\"{{ url_for('tariff') }}\" class=\"{{ 'on' if request.endpoint=='tariff' else '' }}\">Actual & Tariff</a>\n    <a href=\"{{ url_for('distance') }}\" class=\"{{ 'on' if request.endpoint=='distance' else '' }}\">Distance Matrix</a>\n    {% endif %}\n    {% if user.role == 'master' %}\n    <a href=\"{{ url_for('masters') }}\" class=\"{{ 'on' if request.endpoint=='masters' else '' }}\">Masters</a>\n    {% endif %}\n    <a href=\"{{ url_for('notifications') }}\" class=\"{{ 'on' if request.endpoint=='notifications' else '' }}\">Alerts{% if nav_notes %} ({{ nav_notes|length }}){% endif %}</a>\n  </div>\n  <div class=\"nav-right\">\n    <span>{{ user.name }} ({{ user.role }})</span>\n    <a href=\"{{ url_for('change_password') }}\">Change Password</a>\n    <a href=\"{{ url_for('logout') }}\">Logout</a>\n  </div>\n</nav>\n{% endif %}\n<div class=\"wrap\">\n  {% with messages = get_flashed_messages(with_categories=true) %}\n    {% for cat, msg in messages %}\n      <div class=\"alert {{ 'a-ok' if cat=='ok' else 'a-e' }}\">{{ msg }}</div>\n    {% endfor %}\n  {% endwith %}\n  {% if plan_reminder and user and user.role == 'master' %}\n  <div class=\"alert a-e\">\n    <strong>Reminder (21:30 IST):</strong> Pumping plan for effective date <strong>{{ plan_reminder_date }}</strong> is not published yet.\n    Please complete and publish before 22:00 IST.\n    <a class=\"btn btn-p btn-sm\" href=\"{{ url_for('pumping', date=plan_reminder_date) }}\">Open Pumping Planning</a>\n  </div>\n  {% endif %}\n  {% if nav_notes %}\n  <div class=\"alert a-ok\">\n    <strong>Notification:</strong> {{ nav_notes[0].title }} \u2014 {{ nav_notes[0].body }}\n    <a href=\"{{ url_for('notifications') }}\">View all</a>\n  </div>\n  {% endif %}\n  {% block content %}{% endblock %}\n</div>\n<footer class=\"foot\">IHB \u2014 Joint Venture of IndianOil, HPCL & BPCL \u00b7 All quantities in MT</footer>\n</body>\n</html>\n",
    "change_password.html": "{% extends \"base.html\" %}\n{% block title %}Change Password \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Change Password</h1>\n<p class=\"sub\">Update your login password</p>\n<div class=\"sec\" style=\"max-width:420px\">\n  <form method=\"post\">\n    <div class=\"fg\" style=\"margin-bottom:.7rem\">\n      <label>Current Password</label>\n      <input type=\"password\" name=\"old\" required>\n    </div>\n    <div class=\"fg\" style=\"margin-bottom:.7rem\">\n      <label>New Password</label>\n      <input type=\"password\" name=\"new1\" required minlength=\"6\">\n    </div>\n    <div class=\"fg\" style=\"margin-bottom:1rem\">\n      <label>Confirm New Password</label>\n      <input type=\"password\" name=\"new2\" required minlength=\"6\">\n    </div>\n    <button class=\"btn btn-p\" type=\"submit\">Update Password</button>\n  </form>\n</div>\n{% endblock %}\n",
    "dashboard.html": "{% extends \"base.html\" %}\n{% block title %}Dashboard \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Dashboard</h1>\n<p class=\"sub\">OMC-wise & Source-wise summary \u00b7 Shared live data</p>\n\n<div class=\"sec\" style=\"background:{{ '#dcfce7' if mod_ok else '#fef3c7' }};border-color:{{ '#86efac' if mod_ok else '#fcd34d' }}\">\n  <div style=\"display:flex;flex-wrap:wrap;gap:1rem;align-items:center;justify-content:space-between\">\n    <div>\n      <div style=\"font-size:.72rem;font-weight:600;color:#64748b;text-transform:uppercase\">Effective Operational Window (22:00 \u2192 next day 22:00 IST)</div>\n      <div style=\"font-weight:700;color:#1F4E79;margin-top:.15rem\">{{ effective_window }}</div>\n      <div style=\"font-size:.82rem;color:#64748b;margin-top:.2rem\">Effective Date: <strong>{{ effective_date }}</strong> \u00b7 Now: {{ now_ist_str }}</div>\n    </div>\n    <div style=\"text-align:right\">\n      <div style=\"font-size:.72rem;font-weight:600;color:#64748b;text-transform:uppercase\">Plant / Source Edit Window</div>\n      <div style=\"font-weight:700;color:{{ '#166534' if mod_ok else '#92400e' }};margin-top:.15rem\">{{ 'OPEN (12:00\u201321:00 IST)' if mod_ok else 'LOCKED' }}</div>\n      <div style=\"font-size:.8rem;color:#64748b\">{{ mod_msg }}</div>\n    </div>\n  </div>\n</div>\n\n<div class=\"date-bar\">\n  <form method=\"get\" style=\"display:flex;gap:.5rem;align-items:center;flex-wrap:wrap\">\n    <label>Filter by Date:</label>\n    <input type=\"date\" name=\"date\" value=\"{{ date_f }}\">\n    <button class=\"btn btn-p btn-sm\" type=\"submit\">Apply</button>\n    <a class=\"btn btn-sm\" style=\"background:#64748b\" href=\"{{ url_for('dashboard') }}\">All Dates</a>\n  </form>\n</div>\n\n<div class=\"sec\">\n  <h2>Generate Report</h2>\n  <form method=\"post\" action=\"{{ url_for('report') }}\" style=\"display:flex;flex-wrap:wrap;gap:.75rem;align-items:flex-end\">\n    <div class=\"fg\">\n      <label>From Date *</label>\n      <input type=\"date\" name=\"from_date\" required value=\"{{ date_f or effective_date }}\">\n    </div>\n    <div class=\"fg\">\n      <label>To Date *</label>\n      <input type=\"date\" name=\"to_date\" required value=\"{{ date_f or effective_date }}\">\n    </div>\n    <div class=\"fg\">\n      <label>Format *</label>\n      <select name=\"format\" required>\n        <option value=\"excel\">Excel (.xlsx)</option>\n        <option value=\"pdf\">PDF (.pdf)</option>\n      </select>\n    </div>\n    <button class=\"btn btn-p\" type=\"submit\">Download Report</button>\n  </form>\n  <p style=\"font-size:.78rem;color:#64748b;margin-top:.5rem\">Report includes demand, actual, distance, tariff, GST and OMC summary for the selected period.</p>\n</div>\n\n<div class=\"cards\">\n  <div class=\"card\"><div class=\"l\">Total Required</div><div class=\"v\">{{ '%.2f'|format(tot_req) }} <small>MT</small></div></div>\n  <div class=\"card\"><div class=\"l\">Total Actual</div><div class=\"v\">{{ '%.2f'|format(tot_act) }} <small>MT</small></div></div>\n  <div class=\"card\"><div class=\"l\">Plants Reporting</div><div class=\"v\">{{ plants }}</div></div>\n  <div class=\"card\"><div class=\"l\">Grand Total</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_tariff+tot_gst) }}</div></div>\n</div>\n<div class=\"sec\">\n  <h2>OMC-wise Summary (IOCL / BPCL / HPCL)</h2>\n  <table>\n    <thead><tr><th>OMC</th><th>Required (MT)</th><th>Actual (MT)</th><th>Entries</th><th>% Share</th></tr></thead>\n    <tbody>\n    {% for o in OMCS %}\n      <tr>\n        <td><strong>{{ o }}</strong></td>\n        <td>{{ '%.2f'|format(omc[o].req) }}</td>\n        <td>{{ '%.2f'|format(omc[o].act) }}</td>\n        <td>{{ omc[o].c }}</td>\n        <td>{{ '%.1f'|format((omc[o].req/tot_req*100) if tot_req else 0) }}%</td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"sec\">\n  <h2>Source-wise Pumping Requirement</h2>\n  <table>\n    <thead><tr><th>Source</th><th>Required (MT)</th><th>Actual (MT)</th><th>Entries</th><th>% Share</th></tr></thead>\n    <tbody>\n    {% for s in SOURCES if src[s].req or src[s].act %}\n      <tr>\n        <td><strong>{{ s }}</strong></td>\n        <td>{{ '%.2f'|format(src[s].req) }}</td>\n        <td>{{ '%.2f'|format(src[s].act) }}</td>\n        <td>{{ src[s].c }}</td>\n        <td>{{ '%.1f'|format((src[s].req/tot_req*100) if tot_req else 0) }}%</td>\n      </tr>\n    {% else %}\n      <tr><td colspan=\"5\" style=\"text-align:center\">No data</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"sec\">\n  <h2>Billing Summary</h2>\n  <div class=\"cards\">\n    <div class=\"card\"><div class=\"l\">Total Tariff</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_tariff) }}</div></div>\n    <div class=\"card\"><div class=\"l\">GST 18%</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_gst) }}</div></div>\n    <div class=\"card\"><div class=\"l\">Grand Total</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_tariff+tot_gst) }}</div></div>\n  </div>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-top:1rem\">\n    <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:1rem\">\n      <h3 style=\"font-size:.9rem;margin:0 0 .5rem;color:#1F4E79\">Billing by OMC (Grand Total \u20b9)</h3>\n      <canvas id=\"billPie\" height=\"220\"></canvas>\n    </div>\n    <div style=\"background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:1rem\">\n      <h3 style=\"font-size:.9rem;margin:0 0 .5rem;color:#1F4E79\">Tariff vs GST (\u20b9)</h3>\n      <canvas id=\"billBar\" height=\"220\"></canvas>\n    </div>\n  </div>\n  <p style=\"font-size:.8rem;color:#64748b;margin-top:.4rem\">Tariff = (Actual MT \u00d7 Distance Km \u00d7 \u20b93.95) + (Actual MT \u00d7 \u20b90.01) | GST = 18%</p>\n</div>\n<script src=\"https://cdn.jsdelivr.net/npm/chart.js@4.4.1/dist/chart.umd.min.js\"></script>\n<script>\n(function(){\n  const labels = {{ OMCS|tojson }};\n  const bill = {{ bill_omc|tojson }};\n  const grands = labels.map(o => (bill[o] && bill[o].grand) ? bill[o].grand : 0);\n  const tariffs = labels.map(o => (bill[o] && bill[o].tariff) ? bill[o].tariff : 0);\n  const gsts = labels.map(o => (bill[o] && bill[o].gst) ? bill[o].gst : 0);\n  const colors = [\"#1F4E79\",\"#C45C26\",\"#0f766e\"];\n  const pie = document.getElementById(\"billPie\");\n  if(pie && window.Chart){\n    new Chart(pie, {\n      type: \"pie\",\n      data: { labels: labels, datasets: [{ data: grands, backgroundColor: colors }] },\n      options: { plugins: { legend: { position: \"bottom\" } } }\n    });\n  }\n  const bar = document.getElementById(\"billBar\");\n  if(bar && window.Chart){\n    new Chart(bar, {\n      type: \"bar\",\n      data: {\n        labels: labels,\n        datasets: [\n          { label: \"Tariff\", data: tariffs, backgroundColor: \"#1F4E79\" },\n          { label: \"GST 18%\", data: gsts, backgroundColor: \"#C45C26\" }\n        ]\n      },\n      options: {\n        plugins: { legend: { position: \"bottom\" } },\n        scales: { y: { beginAtZero: true } }\n      }\n    });\n  }\n})();\n</script>\n<div class=\"sec\">\n  <h2>Date-wise Billing Summary</h2>\n  <table>\n    <thead><tr><th>Date</th><th>Entries</th><th>Required (MT)</th><th>Actual (MT)</th><th>Tariff (\u20b9)</th><th>GST 18% (\u20b9)</th><th>Grand Total (\u20b9)</th></tr></thead>\n    <tbody>\n    {% for dt in date_list %}\n      {% set r = by_date[dt] %}\n      <tr>\n        <td><strong>{{ dt }}</strong></td>\n        <td>{{ r.c }}</td>\n        <td>{{ '%.2f'|format(r.req) }}</td>\n        <td>{{ '%.2f'|format(r.act) }}</td>\n        <td>\u20b9{{ '%.2f'|format(r.tariff) }}</td>\n        <td>\u20b9{{ '%.2f'|format(r.gst) }}</td>\n        <td><strong>\u20b9{{ '%.2f'|format(r.tariff+r.gst) }}</strong></td>\n      </tr>\n    {% else %}\n      <tr><td colspan=\"7\" style=\"text-align:center\">No billing data</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endblock %}\n",
    "demand.html": "{% extends \"base.html\" %}\n{% block title %}Daily Demand \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Daily Demand Entry</h1>\n<p class=\"sub\">Select plant \u2192 only connected sources. Actual next day. Cannot exceed source availability.</p>\n{% if user.role == 'plant' %}\n<div class=\"alert {{ 'a-ok' if mod_ok else 'a-e' }}\">\n  <strong>{{ 'Edit window OPEN' if mod_ok else 'Edit window LOCKED' }}</strong> \u2014 {{ mod_msg }}<br>\n  <small>Effective window: {{ effective_window }} \u00b7 Now: {{ now_ist_str }}</small>\n</div>\n{% endif %}\n<div class=\"sec\">\n  <h2>Submit New Demand</h2>\n  {% if user.role == 'plant' and not mod_ok %}\n  <p style=\"color:#991b1b;font-weight:600;margin-bottom:.75rem\">You cannot submit or modify demand right now. Please try between 12:00 and 21:00 IST.</p>\n  {% endif %}\n  <form method=\"post\">\n    <div class=\"frm\">\n      <div class=\"fg\">\n        <label>Bottling Plant *</label>\n        <select name=\"plant\" id=\"plantSel\" required {% if user.role=='plant' %}disabled{% endif %} onchange=\"loadSrc()\">\n          {% if user.role=='plant' %}\n            <option value=\"{{ user.plant }}\">{{ user.plant }}</option>\n          {% else %}\n            <option value=\"\">Select Plant</option>\n            {% for p in PLANTS %}\n            <option value=\"{{ p[0] }}\">{{ p[0] }} ({{ p[1] }})</option>\n            {% endfor %}\n          {% endif %}\n        </select>\n        {% if user.role=='plant' %}<input type=\"hidden\" name=\"plant\" value=\"{{ user.plant }}\">{% endif %}\n      </div>\n      <div class=\"fg\">\n        <label>Preferred Source *</label>\n        <select name=\"source\" id=\"srcSel\" required>\n          <option value=\"\">Select plant first</option>\n        </select>\n      </div>\n      <div class=\"fg\">\n        <label>Date *</label>\n        <input type=\"date\" name=\"date\" value=\"{{ today }}\" required>\n      </div>\n    </div>\n    <div class=\"frm\">\n      <div class=\"fg\">\n        <label>Required Qty (MT) *</label>\n        <input type=\"number\" name=\"req\" step=\"0.001\" min=\"0\" required placeholder=\"e.g. 450\">\n      </div>\n      <div class=\"fg\">\n        <label>Available Ullage (MT)</label>\n        <input type=\"number\" name=\"ullage\" step=\"0.001\" min=\"0\" placeholder=\"e.g. 600\">\n      </div>\n      <div class=\"fg\">\n        <label>Priority</label>\n        <select name=\"priority\">\n          <option>Normal</option><option>High</option><option>Critical</option>\n        </select>\n      </div>\n      <div class=\"fg\">\n        <label>Remarks</label>\n        <input type=\"text\" name=\"remarks\" placeholder=\"Optional\">\n      </div>\n    </div>\n    {% if user.role == 'plant' and not mod_ok %}\n    <button class=\"btn btn-p\" type=\"button\" disabled style=\"opacity:.5\">Submit Demand (Locked)</button>\n    {% else %}\n    <button class=\"btn btn-p\" type=\"submit\">Submit Demand</button>\n    {% endif %}\n  </form>\n</div>\n<div class=\"sec\">\n  <h2>Demand Records</h2>\n  <div class=\"date-bar\">\n    <form method=\"get\" style=\"display:flex;gap:.5rem;align-items:center\">\n      <label>Filter by Date:</label>\n      <input type=\"date\" name=\"date\" value=\"{{ date_f }}\">\n      <button class=\"btn btn-p btn-sm\" type=\"submit\">Apply</button>\n      <a class=\"btn btn-sm\" style=\"background:#64748b\" href=\"{{ url_for('demand') }}\">All</a>\n    </form>\n  </div>\n  <table>\n    <thead>\n      <tr>\n        <th>#</th><th>Date</th><th>Plant</th><th>OMC</th><th>Source</th>\n        <th>Required</th><th>Actual</th><th>Priority</th><th>Remarks</th>\n        {% if user.role=='master' %}<th>Action</th>{% endif %}\n      </tr>\n    </thead>\n    <tbody>\n    {% for d in rows %}\n      <tr>\n        <td>{{ d.id }}</td>\n        <td>{{ d.date }}</td>\n        <td>{{ d.plant }}</td>\n        <td>{{ d.omc }}</td>\n        <td>{{ d.source }}</td>\n        <td>{{ '%.3f'|format(d.req) }}</td>\n        <td>\n          {% if d.actual is not none %}\n            {{ '%.3f'|format(d.actual) }}\n          {% else %}\n            <form method=\"post\" action=\"{{ url_for('set_actual', did=d.id) }}\" style=\"display:flex;gap:.3rem;flex-wrap:wrap;align-items:center\">\n              <input type=\"number\" name=\"actual\" step=\"0.001\" min=\"0\" placeholder=\"0.000\" style=\"width:80px;padding:.2rem\" required>\n              <input type=\"text\" name=\"remarks\" placeholder=\"Remark if Actual < Required\" style=\"width:150px;padding:.2rem;font-size:.8rem\">\n              <button class=\"btn btn-ok btn-sm\" type=\"submit\">Save</button>\n            </form>\n          {% endif %}\n        </td>\n        <td>{{ d.priority }}</td>\n        <td>{{ d.remarks or '\u2014' }}</td>\n        {% if user.role=='master' %}\n        <td>\n          <form method=\"post\" action=\"{{ url_for('delete_demand', did=d.id) }}\" onsubmit=\"return confirm('Delete?')\">\n            <button class=\"btn btn-e btn-sm\" type=\"submit\">Del</button>\n          </form>\n        </td>\n        {% endif %}\n      </tr>\n    {% else %}\n      <tr><td colspan=\"10\" style=\"text-align:center\">No records</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n<script>\nconst DIST = {{ DIST|tojson }};\nfunction loadSrc(){\n  const plant = document.getElementById(\"plantSel\").value;\n  const sel = document.getElementById(\"srcSel\");\n  sel.innerHTML = \"\";\n  const d = DIST[plant] || {};\n  const keys = Object.keys(d);\n  if(!keys.length){ sel.innerHTML = '<option value=\"\">No connected sources</option>'; return; }\n  keys.forEach(k => {\n    const o = document.createElement(\"option\");\n    o.value = k; o.textContent = k;\n    sel.appendChild(o);\n  });\n}\n{% if user.role=='plant' %}\ndocument.addEventListener(\"DOMContentLoaded\", loadSrc);\n{% endif %}\n</script>\n{% endblock %}\n",
    "distance.html": "{% extends \"base.html\" %}\n{% block title %}Distance Matrix \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Distance Matrix (Km)</h1>\n<p class=\"sub\">Green = Connected \u00b7 Red = Not connected</p>\n<div class=\"sec\">\n  <table>\n    <thead>\n      <tr>\n        <th>#</th><th>Plant</th><th>OMC</th>\n        {% for s in SOURCES %}<th>{{ s }}</th>{% endfor %}\n      </tr>\n    </thead>\n    <tbody>\n    {% for p in PLANTS %}\n      <tr>\n        <td>{{ loop.index }}</td>\n        <td>{{ p[0] }}</td>\n        <td>{{ p[1] }}</td>\n        {% for s in SOURCES %}\n          {% set km = DIST.get(p[0], {}).get(s) %}\n          {% if km %}\n            <td class=\"g\" style=\"text-align:center\">{{ '%.3f'|format(km) }}</td>\n          {% else %}\n            <td class=\"r\" style=\"text-align:center\">\u2014</td>\n          {% endif %}\n        {% endfor %}\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endblock %}\n",
    "login.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Login \u00b7 KGPL LPG System</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:system-ui,sans-serif;min-height:100vh;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#1F4E79,#2E86AB);padding:1.5rem}\n.box{background:#fff;border-radius:14px;padding:2rem;width:100%;max-width:400px;box-shadow:0 20px 50px rgba(0,0,0,.25)}\nh1{color:#1F4E79;font-size:1.2rem;text-align:center}\np{color:#64748b;font-size:.85rem;text-align:center;margin:.3rem 0 1.2rem}\nlabel{display:block;font-size:.75rem;font-weight:600;color:#64748b;margin-bottom:.25rem}\ninput{width:100%;padding:.55rem .7rem;border:1px solid #e2e8f0;border-radius:8px;font-size:.95rem;margin-bottom:.85rem}\nbutton{width:100%;padding:.65rem;background:#1F4E79;color:#fff;border:none;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer}\n.err{background:#fee2e2;color:#991b1b;padding:.55rem .7rem;border-radius:8px;margin-bottom:.85rem;font-size:.85rem}\n</style>\n</head>\n<body>\n<div class=\"box\">\n  <h1>KGPL LPG System</h1>\n  <p>Kandla\u2013Gorakhpur Pipeline \u00b7 IHB</p>\n  {% with messages = get_flashed_messages(with_categories=true) %}\n    {% for cat, msg in messages %}\n      <div class=\"err\">{{ msg }}</div>\n    {% endfor %}\n  {% endwith %}\n  <form method=\"post\">\n    <label>User ID</label>\n    <input type=\"text\" name=\"user_id\" required autofocus autocomplete=\"username\">\n    <label>Password</label>\n    <input type=\"password\" name=\"password\" required autocomplete=\"current-password\">\n    <button type=\"submit\">Login</button>\n  </form>\n</div>\n</body>\n</html>\n",
    "masters.html": "{% extends \"base.html\" %}\n{% block title %}Masters \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Master Data</h1>\n<p class=\"sub\">Plants, Sources & User management</p>\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:1rem\">\n  <div class=\"sec\">\n    <h2>Bottling Plants</h2>\n    <table>\n      <thead><tr><th>#</th><th>Plant</th><th>OMC</th><th>Region</th></tr></thead>\n      <tbody>\n      {% for p in PLANTS %}\n        <tr><td>{{ loop.index }}</td><td>{{ p[0] }}</td><td>{{ p[1] }}</td><td>{{ p[2] }}</td></tr>\n      {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  <div class=\"sec\">\n    <h2>Sources</h2>\n    <table>\n      <thead><tr><th>#</th><th>Source</th></tr></thead>\n      <tbody>\n      {% for s in SOURCES %}\n        <tr><td>{{ loop.index }}</td><td>{{ s }}</td></tr>\n      {% endfor %}\n      </tbody>\n    </table>\n  </div>\n</div>\n<div class=\"sec\">\n  <h2>Users & Password Reset</h2>\n  <table>\n    <thead><tr><th>Role</th><th>Name</th><th>User ID</th><th>Scope</th><th>Reset Password</th></tr></thead>\n    <tbody>\n    {% for u in users %}\n      <tr>\n        <td>{{ u.role }}</td>\n        <td>{{ u.name }}</td>\n        <td><code>{{ u.id }}</code></td>\n        <td>{{ u.plant or u.source or 'All' }}</td>\n        <td>\n          <form method=\"post\" action=\"{{ url_for('reset_password') }}\" style=\"display:flex;gap:.3rem;align-items:center\">\n            <input type=\"hidden\" name=\"user_id\" value=\"{{ u.id }}\">\n            <input type=\"password\" name=\"new_pass\" placeholder=\"New password\" minlength=\"6\" required style=\"padding:.25rem;width:130px;font-size:.8rem\">\n            <button class=\"btn btn-p btn-sm\" type=\"submit\">Reset</button>\n          </form>\n        </td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endblock %}\n",
    "notifications.html": "{% extends \"base.html\" %}\n{% block title %}Alerts \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Notifications / Alerts</h1>\n<p class=\"sub\">Plan publish messages and reminders</p>\n<div class=\"sec\">\n  <table>\n    <thead><tr><th>When</th><th>Title</th><th>Message</th></tr></thead>\n    <tbody>\n    {% for r in rows %}\n      <tr>\n        <td>{{ r.created_at }}</td>\n        <td><strong>{{ r.title }}</strong></td>\n        <td>{{ r.body }}</td>\n      </tr>\n    {% else %}\n      <tr><td colspan=\"3\" style=\"text-align:center\">No notifications</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endblock %}\n",
    "pumping.html": "{% extends \"base.html\" %}\n{% block title %}Pumping Planning \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Pumping Planning (Master)</h1>\n<p class=\"sub\">Build schedule from Daily Demand \u00b7 Set flow rate & start time \u00b7 Publish before 22:00 IST \u00b7 PDF format matches Master Plan sheet</p>\n\n<form method=\"get\" class=\"date-bar\">\n  <label>Plan Date:</label>\n  <input type=\"date\" name=\"date\" value=\"{{ plan_date }}\" onchange=\"this.form.submit()\">\n  <span style=\"color:#64748b\">Status: <strong>{{ plan.status if plan else 'new' }}</strong>\n  {% if plan and plan.published_at %} \u00b7 Published: {{ plan.published_at }}{% endif %}</span>\n</form>\n\n<form method=\"post\">\n  <input type=\"hidden\" name=\"date\" value=\"{{ plan_date }}\">\n  <div class=\"sec\" style=\"overflow-x:auto\">\n    <h2>PUMPING SCHEDULE \u2014 MASTER PLAN & ALLOCATION</h2>\n    <table>\n      <thead>\n        <tr>\n          <th>Seq</th><th>Source</th><th>Plant</th><th>Allocation (MT)</th>\n          <th>Flow Rate (MT/hr)</th><th>Manual Start (DD-Mon-YYYY HH:MM)</th>\n          <th>Start Time</th><th>Duration (hrs)</th><th>Completion Time</th><th>Notes</th>\n        </tr>\n      </thead>\n      <tbody>\n      {% for it in items %}\n        <tr>\n          <td><input type=\"number\" name=\"seq\" value=\"{{ it.seq }}\" style=\"width:50px\"></td>\n          <td>\n            <input type=\"hidden\" name=\"source\" value=\"{{ it.source }}\">{{ it.source }}\n            <input type=\"hidden\" name=\"demand_id\" value=\"{{ it.demand_id or '' }}\">\n          </td>\n          <td>\n            <input type=\"hidden\" name=\"plant\" value=\"{{ it.plant }}\">{{ it.plant }}\n          </td>\n          <td><input type=\"number\" step=\"0.001\" name=\"allocation\" value=\"{{ it.allocation }}\" style=\"width:90px\"></td>\n          <td><input type=\"number\" step=\"1\" name=\"flow_rate\" value=\"{{ it.flow_rate or 70 }}\" style=\"width:80px\"></td>\n          <td><input type=\"text\" name=\"manual_start\" value=\"{{ it.manual_start or '' }}\" placeholder=\"23-Nov-2026 22:00\" style=\"width:150px\"></td>\n          <td>{{ it.start_time or '\u2014' }}</td>\n          <td>{{ '%.2f'|format(it.duration_hrs) if it.duration_hrs else '\u2014' }}</td>\n          <td>{{ it.completion_time or '\u2014' }}</td>\n          <td><input type=\"text\" name=\"notes\" value=\"{{ it.notes or '' }}\" style=\"width:100px\"></td>\n        </tr>\n      {% else %}\n        <tr><td colspan=\"10\" style=\"text-align:center\">No demand found for this date. Enter Daily Demand first.</td></tr>\n      {% endfor %}\n      </tbody>\n    </table>\n  </div>\n\n  {% if src_tot %}\n  <div class=\"sec\">\n    <h2>Source-wise totals</h2>\n    <table>\n      <thead><tr><th>Source</th><th>Total Allocation (MT)</th></tr></thead>\n      <tbody>\n      {% for s,t in src_tot.items() %}\n        <tr><td>{{ s }}</td><td>{{ '%.2f'|format(t) }}</td></tr>\n      {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  {% endif %}\n\n  <div style=\"display:flex;flex-wrap:wrap;gap:.6rem;margin-bottom:1rem\">\n    <button class=\"btn btn-p\" type=\"submit\" name=\"action\" value=\"save\">Save & Recalculate Times</button>\n    <button class=\"btn btn-ok\" type=\"submit\" name=\"action\" value=\"publish\">Publish Plan (notify Plant & Source)</button>\n    <button class=\"btn btn-p\" type=\"submit\" name=\"action\" value=\"pdf\">Save & Download PDF</button>\n    <a class=\"btn btn-p\" href=\"{{ url_for('pumping_pdf', date=plan_date) }}\">Download PDF only</a>\n  </div>\n  <p style=\"font-size:.8rem;color:#64748b\">Duration = Allocation \u00f7 Flow Rate. If Manual Start is blank, start time follows previous completion on the same source. Publish before 22:00 IST.</p>\n</form>\n{% endblock %}\n",
    "schedule.html": "{% extends \"base.html\" %}\n{% block title %}Schedule \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Pumping Schedule</h1>\n<p class=\"sub\">Delivery / uplift timing from published Master plan \u00b7 Flow rate, start & completion</p>\n\n<form method=\"get\" class=\"date-bar\">\n  <label>Date:</label>\n  <input type=\"date\" name=\"date\" value=\"{{ plan_date }}\" onchange=\"this.form.submit()\">\n  {% if plan %}\n  <span>Status: <strong>{{ plan.status }}</strong></span>\n  {% endif %}\n</form>\n\n{% if not plan or (plan.status != 'published' and user.role != 'master') %}\n  <div class=\"alert a-e\">No published pumping plan for this date yet. Master will publish after planning.</div>\n{% endif %}\n\n<div class=\"sec\" style=\"overflow-x:auto\">\n  <h2>Your schedule</h2>\n  <table>\n    <thead>\n      <tr>\n        <th>Seq</th><th>Source</th><th>Plant</th><th>Allocation (MT)</th>\n        <th>Flow Rate (MT/hr)</th><th>Start Time</th><th>Duration (hrs)</th><th>Completion Time</th><th>Notes</th>\n      </tr>\n    </thead>\n    <tbody>\n    {% for it in items %}\n      <tr>\n        <td>{{ it.seq }}</td>\n        <td>{{ it.source }}</td>\n        <td>{{ it.plant }}</td>\n        <td>{{ '%.2f'|format(it.allocation) }}</td>\n        <td>{{ it.flow_rate or '\u2014' }}</td>\n        <td><strong>{{ it.start_time or '\u2014' }}</strong></td>\n        <td>{{ '%.2f'|format(it.duration_hrs) if it.duration_hrs else '\u2014' }}</td>\n        <td><strong>{{ it.completion_time or '\u2014' }}</strong></td>\n        <td>{{ it.notes or '' }}</td>\n      </tr>\n    {% else %}\n      <tr><td colspan=\"9\" style=\"text-align:center\">No rows for your plant/source</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% if user.role == 'master' %}\n<p><a class=\"btn btn-p\" href=\"{{ url_for('pumping', date=plan_date) }}\">Edit in Pumping Planning</a>\n<a class=\"btn btn-p\" href=\"{{ url_for('pumping_pdf', date=plan_date) }}\">Download PDF</a></p>\n{% endif %}\n{% endblock %}\n",
    "tariff.html": "{% extends \"base.html\" %}\n{% block title %}Actual & Tariff \u00b7 KGPL{% endblock %}\n{% block content %}\n<h1>Actual Receipt & Tariff</h1>\n<p class=\"sub\">Variable \u20b93.95/MT/Km + Fixed \u20b90.01/MT + GST 18%</p>\n<div class=\"date-bar\">\n  <form method=\"get\" style=\"display:flex;gap:.5rem;align-items:center\">\n    <label>Filter by Date:</label>\n    <input type=\"date\" name=\"date\" value=\"{{ date_f }}\">\n    <button class=\"btn btn-p btn-sm\" type=\"submit\">Apply</button>\n    <a class=\"btn btn-sm\" style=\"background:#64748b\" href=\"{{ url_for('tariff') }}\">All</a>\n  </form>\n</div>\n<div class=\"cards\">\n  <div class=\"card\"><div class=\"l\">Total Tariff</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_t) }}</div></div>\n  <div class=\"card\"><div class=\"l\">Total GST 18%</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_g) }}</div></div>\n  <div class=\"card\"><div class=\"l\">Grand Total</div><div class=\"v\" style=\"font-size:1.05rem\">\u20b9{{ '%.2f'|format(tot_t+tot_g) }}</div></div>\n</div>\n<div class=\"sec\">\n  <h2>OMC-wise Breakup</h2>\n  <table>\n    <thead><tr><th>OMC</th><th>Entries</th><th>Required</th><th>Actual</th><th>Tariff</th><th>GST 18%</th><th>Grand Total</th><th>% of Total</th></tr></thead>\n    <tbody>\n    {% set grand_all = tot_t + tot_g %}\n    {% for o in OMCS %}\n      {% set r = omc_map[o] %}\n      {% set g = r.tariff + r.gst %}\n      <tr>\n        <td><strong>{{ o }}</strong></td>\n        <td>{{ r.c }}</td>\n        <td>{{ '%.2f'|format(r.req) }}</td>\n        <td>{{ '%.2f'|format(r.act) }}</td>\n        <td>\u20b9{{ '%.2f'|format(r.tariff) }}</td>\n        <td>\u20b9{{ '%.2f'|format(r.gst) }}</td>\n        <td><strong>\u20b9{{ '%.2f'|format(g) }}</strong></td>\n        <td>{{ '%.1f'|format((g/grand_all*100) if grand_all else 0) }}%</td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"sec\">\n  <h2>Tariff Details</h2>\n  <table>\n    <thead>\n      <tr>\n        <th>Date</th><th>Plant</th><th>OMC</th><th>Source</th><th>Dist (Km)</th>\n        <th>Required</th><th>Actual</th><th>Variable</th><th>Fixed</th><th>Tariff</th><th>GST</th><th>Grand Total</th>\n      </tr>\n    </thead>\n    <tbody>\n    {% for d in details %}\n      <tr>\n        <td>{{ d.date }}</td>\n        <td>{{ d.plant }}</td>\n        <td>{{ d.omc }}</td>\n        <td>{{ d.source }}</td>\n        <td>{{ '%.3f'|format(d.km) }}</td>\n        <td>{{ '%.3f'|format(d.req) }}</td>\n        <td><strong>{{ '%.3f'|format(d.actual) }}</strong></td>\n        <td>\u20b9{{ '%.2f'|format(d.var) }}</td>\n        <td>\u20b9{{ '%.2f'|format(d.fix) }}</td>\n        <td>\u20b9{{ '%.2f'|format(d.tariff) }}</td>\n        <td>\u20b9{{ '%.2f'|format(d.gst) }}</td>\n        <td><strong>\u20b9{{ '%.2f'|format(d.grand) }}</strong></td>\n      </tr>\n    {% else %}\n      <tr><td colspan=\"12\" style=\"text-align:center\">No actual quantities yet</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endblock %}\n",
}
